import{_ as e,o as d,c as a,a0 as c}from"./chunks/framework.DhQjJcnt.js";const p=JSON.parse('{"title":"Gate & mốc kiểm định","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/gates.md","filePath":"workflows/gates.md"}'),o={name:"workflows/gates.md"};function n(s,t,r,i,h,l){return d(),a("div",null,[...t[0]||(t[0]=[c(`<h1 id="gate-moc-kiem-đinh" tabindex="-1">Gate &amp; mốc kiểm định <a class="header-anchor" href="#gate-moc-kiem-đinh" aria-label="Permalink to &quot;Gate &amp; mốc kiểm định&quot;">​</a></h1><p><strong>Phạm vi (SSOT):</strong> <strong>khi</strong> chạy <code>flowgrid audit *</code>, <code>cases:gate</code>; chuyển phase an toàn; chuỗi completeness artifact (bundle ↔ TC ↔ FE-BE ↔ scenario).</p><p><strong>Không viết ở đây:</strong> tham số lệnh → <a href="./../references/cli-and-commands.html#audit--harness-pr-workflow">references/cli-and-commands.md</a>.</p><p><strong>Bối cảnh:</strong> <a href="./">index.md</a> · grill người: <a href="./grill-and-human-review.html">grill-and-human-review.md</a>.</p><hr><h2 id="khi-nao-chay-theo-lane" tabindex="-1">Khi nào chạy (theo lane) <a class="header-anchor" href="#khi-nao-chay-theo-lane" aria-label="Permalink to &quot;Khi nào chạy (theo lane)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mốc</th><th>Lệnh / skill gợi ý</th><th>Ai đọc kết quả</th></tr></thead><tbody><tr><td>Sau <code>/spec</code>, <code>/update-spec</code></td><td><code>flowgrid audit spec</code> (<code>--type</code>)</td><td>BQA / Dev grill</td></tr><tr><td>Trước đóng testcase</td><td><code>cases:check</code>, <code>audit testcase</code> (+ <code>--bundle</code>)</td><td>QA</td></tr><tr><td>Release tests-docs</td><td><code>cases:gate</code> (<code>--strict</code>, <code>--docs-root</code>)</td><td>QA + reviewer</td></tr><tr><td>Trước / sau wire</td><td><code>audit fe-be</code>, <code>audit scenario</code>, E2E scoped</td><td>Dev FE + QA</td></tr><tr><td>Legacy adoption</td><td><code>audit legacy</code></td><td>Lead</td></tr></tbody></table><p>Tool <strong>không</strong> tự chạy — member gọi CLI/skill. Bỏ bước → rủi ro process (xem <a href="./grill-and-human-review.html">grill-and-human-review.md</a>).</p><hr><h2 id="luong-tham-chieu-team-lam-đung" tabindex="-1">Luồng tham chiếu (team làm đúng) <a class="header-anchor" href="#luong-tham-chieu-team-lam-đung" aria-label="Permalink to &quot;Luồng tham chiếu (team làm đúng)&quot;">​</a></h2><h3 id="tao-moi-function-man" tabindex="-1">Tạo mới function / màn <a class="header-anchor" href="#tao-moi-function-man" aria-label="Permalink to &quot;Tạo mới function / màn&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/spec → audit spec → grill-bqa / grill-dev → split</span></span>
<span class="line"><span>→ /testcase (bundle SSOT, schema v2, traceability)</span></span>
<span class="line"><span>→ cases:gate [--strict] + FLOWGRID_DOCS_ROOT</span></span>
<span class="line"><span>→ testcase:gen → Playwright (e2e-root)</span></span>
<span class="line"><span>→ (policy) manual E2E một vòng trước release</span></span></code></pre></div><h3 id="change-request" tabindex="-1">Change request <a class="header-anchor" href="#change-request" aria-label="Permalink to &quot;Change request&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/update-spec → audit spec (bắt buộc trong skill) → split</span></span>
<span class="line"><span>→ patch TC cùng W-* / bundle impact</span></span>
<span class="line"><span>→ cases:gate --strict</span></span>
<span class="line"><span>→ /grill-testcase (đọc gate output)</span></span>
<span class="line"><span>→ gen + IT + manual E2E (policy team)</span></span></code></pre></div><hr><h2 id="chuoi-completeness-ssot-chain" tabindex="-1">Chuỗi completeness (SSOT chain) <a class="header-anchor" href="#chuoi-completeness-ssot-chain" aria-label="Permalink to &quot;Chuỗi completeness (SSOT chain)&quot;">​</a></h2><p>Policy testcase: <code>/testcase</code> đọc <strong><code>*.bundle.yaml</code></strong> (không tách đọc IR lẻ). Thiếu bundle hoặc <code>flowgrid check</code> lệch → STOP, split từ docs-hub trước.</p><table tabindex="0"><thead><tr><th>Phase</th><th>Đã ship (engine/skill)</th><th>Mục tiêu</th></tr></thead><tbody><tr><td><strong>A</strong></td><td><code>audit testcase --bundle</code></td><td>Scenario/AC/action ↔ TC</td></tr><tr><td><strong>B</strong></td><td><code>audit fe-be</code> + grill-dev</td><td><code>apiRef</code> ↔ <code>01-backend-spec</code></td></tr><tr><td><strong>C</strong></td><td><code>audit scenario</code> + <code>/scenario</code></td><td><code>FLOW</code> / SC <code>screens[]</code> ↔ <code>cases/**</code></td></tr><tr><td><strong>D</strong></td><td><code>/update-spec</code> rules</td><td>Delta design ↔ <code>userStories</code> / AC</td></tr><tr><td><strong>F</strong></td><td><code>cases:gate</code>, TC schema v2</td><td>Release gate tests-docs</td></tr><tr><td><strong>E</strong></td><td><em>(DevOps, optional)</em></td><td>CI: <code>check</code>, <code>cases:gate</code>, <code>doctor</code></td></tr></tbody></table><hr><h2 id="close-one-function" tabindex="-1">Đóng một function (<code>W-*</code>) <a class="header-anchor" href="#close-one-function" aria-label="Permalink to &quot;Đóng một function (\`W-*\`) {#close-one-function}&quot;">​</a></h2><p>Chuỗi gợi ý trước khi coi <strong>một leaf</strong> (màn / API seq) đã khớp artifact — không thay checklist release cả sản phẩm. Macro team: <a href="./#full-cycle">index.md</a>.</p><table tabindex="0"><thead><tr><th>#</th><th>Mốc</th><th>Lệnh / skill</th><th>Đọc kết quả</th></tr></thead><tbody><tr><td>1</td><td>Spec &amp; grill</td><td><code>flowgrid audit spec</code> (<code>--type</code>) · <code>/grill-bqa</code> · <code>/grill-dev</code></td><td><code>gaps[]</code> / confirms xử lý; member chốt</td></tr><tr><td>2</td><td>IR đồng bộ</td><td><code>flowgrid split</code> · <code>flowgrid check</code></td><td>Bundle ↔ <code>ir/*</code> khớp trước testcase/codegen</td></tr><tr><td>3</td><td>Plan tests-docs</td><td><code>/testcase</code> · <code>/grill-testcase</code></td><td><code>cases:check</code> · <code>audit testcase --bundle</code></td></tr><tr><td>4</td><td>Gate plan</td><td><code>cases:gate --strict</code> + <code>FLOWGRID_DOCS_ROOT</code></td><td>Schema v2, trace, ma trận facet</td></tr><tr><td>5</td><td>Contract BE</td><td><code>audit api</code> · <code>audit fe-be</code></td><td><code>apiRef</code> ↔ <code>01-backend-spec.yaml</code></td></tr><tr><td>6</td><td>Cross-flow (nếu SC)</td><td><code>audit scenario</code></td><td><code>screens[]</code> có <code>TC-*.yaml</code> hoặc defer có <code>QA-*</code></td></tr><tr><td>7</td><td>E2E (e2e-root)</td><td><code>testcase:gen</code> · <code>/test</code> · <code>/grill-test</code></td><td>Matrix TC ↔ PO ↔ <code>*.spec.ts</code></td></tr><tr><td>8</td><td>Plan ↔ chạy</td><td><code>flowgrid audit e2e</code> (<code>--e2e-root</code>, <code>--tests-docs</code>)</td><td>Plan hub khớp spec Playwright scoped</td></tr><tr><td>9</td><td>Wire (API thật)</td><td><code>/wire</code> · E2E post-wire scoped</td><td><code>audit fe-be</code> · lifecycle <code>wire</code> trên route</td></tr></tbody></table><p>Bỏ bước → gap có thể lọt; toolkit không chạy chuỗi tự động — member hoặc CI gọi từng mốc (<a href="./grill-and-human-review.html">grill-and-human-review.md</a>).</p><hr><h2 id="bang-audit-↔-artifact" tabindex="-1">Bảng audit ↔ artifact <a class="header-anchor" href="#bang-audit-↔-artifact" aria-label="Permalink to &quot;Bảng audit ↔ artifact&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lệnh</th><th>Kiểm tra chính</th></tr></thead><tbody><tr><td><code>audit spec</code></td><td>Bundle + UX affordance (<code>UX_*</code>, <code>confirms</code>)</td></tr><tr><td><code>audit api</code></td><td>Contract API YAML</td></tr><tr><td><code>audit testcase</code></td><td>TC v2; <code>--bundle</code> cross-ref bundle</td></tr><tr><td><code>audit fe-be</code></td><td>Bundle <code>apiRef</code> vs backend spec</td></tr><tr><td><code>audit scenario</code></td><td>SC screens vs TC</td></tr><tr><td><code>audit flow</code></td><td><code>FLOW-*.md</code></td></tr><tr><td><code>audit legacy</code></td><td>Adoption index</td></tr><tr><td><code>cases:gate</code></td><td>Schema + audit TC + trace + facets</td></tr></tbody></table><hr><h2 id="cong-cu-phan-tich-rui-ro-human-in-the-loop" tabindex="-1">Công cụ phân tích rủi ro (human-in-the-loop) <a class="header-anchor" href="#cong-cu-phan-tich-rui-ro-human-in-the-loop" aria-label="Permalink to &quot;Công cụ phân tích rủi ro (human-in-the-loop)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lệnh</th><th>Cảnh báo</th><th>Người quyết định</th></tr></thead><tbody><tr><td><code>audit spec</code></td><td>Cấu trúc, UX affordance</td><td>BQA / Dev grill</td></tr><tr><td><code>cases:gate</code></td><td>Schema, matrix facet, trace bundle</td><td>QA / grill-testcase</td></tr><tr><td><code>audit testcase --bundle</code></td><td>Scenario / AC / action chưa map</td><td>Author TC</td></tr><tr><td><code>audit scenario</code></td><td><code>screens[]</code> chưa có TC</td><td>Owner cross-flow</td></tr></tbody></table><p>Output <code>--json</code> dùng cho <strong>review và sign-off</strong>, không thay judgment “đủ cho release”.</p><h3 id="e2e-automation-vs-manual" tabindex="-1">E2E automation vs manual <a class="header-anchor" href="#e2e-automation-vs-manual" aria-label="Permalink to &quot;E2E automation vs manual&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Lớp</th><th>Mục đích</th></tr></thead><tbody><tr><td>Plan SSOT (<code>TC-*.yaml</code>)</td><td>Matrix, steps, testIds, trace bundle</td></tr><tr><td>Generated IT (Playwright)</td><td>Regression trên FE — <code>testcase:gen</code></td></tr><tr><td>Manual E2E một vòng</td><td>Degrade / UX / ngữ cảnh — <strong>policy team</strong>, không encode bắt buộc trong toolkit</td></tr></tbody></table><p>Playwright chứng minh code chạy theo plan đã author; chất lượng plan và cập nhật sau CR vẫn là người.</p>`,33)])])}const g=e(o,[["render",n]]);export{p as __pageData,g as default};
